public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();

        int[][] boxes = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                boxes[i][j] = sc.nextInt();
            }
        }

        int minMoves = Integer.MAX_VALUE;

        // Try each box as joker (or no joker with -1)
        for (int joker = -1; joker < n; joker++) {
            int moves = 0;

            // For each color, find which box has the most cards
            int[] colorBox = new int[m];
            Arrays.fill(colorBox, -1);

            for (int c = 0; c < m; c++) {
                int maxBox = -1;
                int maxCount = 0;

                for (int i = 0; i < n; i++) {
                    if (i != joker && boxes[i][c] > maxCount) {
                        maxCount = boxes[i][c];
                        maxBox = i;
                    }
                }

                if (maxCount > 0) {
                    colorBox[c] = maxBox;
                }
            }

            // Count moves needed
            for (int i = 0; i < n; i++) {
                if (i == joker) continue;

                int assignedColor = -1;
                for (int c = 0; c < m; c++) {
                    if (colorBox[c] == i) {
                        assignedColor = c;
                        break;
                    }
                }

                int moveCount = 0;
                for (int c = 0; c < m; c++) {
                    if (boxes[i][c] > 0 && c != assignedColor) {
                        moveCount++;
                    }
                }

                if (moveCount > 0) {
                    moves += moveCount;
                }
            }

            minMoves = Math.min(minMoves, moves);
        }

        System.out.println(minMoves);
        sc.close();
    }
}

