public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        int[][] cost = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                cost[i][j] = sc.nextInt();
            }
        }

        String state = sc.next();
        int p = sc.nextInt();

        int initial = 0;
        int count = 0;
        for (int i = 0; i < n; i++) {
            if (state.charAt(i) == 'Y') {
                initial |= (1 << i);
                count++;
            }
        }

        if (count >= p) {
            System.out.println(0);
            return;
        }

        if (count == 0) {
            System.out.println(-1);
            return;
        }

        final int INF = 1000000000;
        int[] dp = new int[1 << n];
        Arrays.fill(dp, INF);
        dp[initial] = 0;

        for (int mask = 0; mask < (1 << n); mask++) {
            if (dp[mask] == INF) continue;

            int bits = Integer.bitCount(mask);
            if (bits >= p) continue;

            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    for (int j = 0; j < n; j++) {
                        if ((mask & (1 << j)) == 0) {
                            int newMask = mask | (1 << j);
                            dp[newMask] = Math.min(dp[newMask], dp[mask] + cost[i][j]);
                        }
                    }
                }
            }
        }

        int ans = INF;
        for (int mask = 0; mask < (1 << n); mask++) {
            if (Integer.bitCount(mask) >= p) {
                ans = Math.min(ans, dp[mask]);
            }
        }

        System.out.println(ans == INF ? -1 : ans);
        sc.close();
    }
}

