public class Main {
    static int n, m;
    static char[][] board;
    static int[][] dp;
    static boolean[][] visited;
    static int[] dx = {-1, 1, 0, 0};
    static int[] dy = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();

        board = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            for (int j = 0; j < m; j++) {
                board[i][j] = line.charAt(j);
            }
        }

        dp = new int[n][m];
        visited = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dp[i], -1);
        }

        System.out.println(dfs(0, 0));
        sc.close();
    }

    static int dfs(int x, int y) {
        if (x < 0 || x >= n || y < 0 || y >= m || board[x][y] == 'H') {
            return 0;
        }

        if (visited[x][y]) {
            return -1;
        }

        if (dp[x][y] != -1) {
            return dp[x][y];
        }

        visited[x][y] = true;
        int num = board[x][y] - '0';
        int maxMoves = 0;

        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i] * num;
            int ny = y + dy[i] * num;

            int result = dfs(nx, ny);
            if (result == -1) {
                visited[x][y] = false;
                return -1;
            }

            maxMoves = Math.max(maxMoves, result);
        }

        visited[x][y] = false;
        dp[x][y] = maxMoves + 1;
        return dp[x][y];
    }
}

