        int trailing = 0;
        for (int i = s1.length() - 1; i >= 0; i--) {
            if (s1.charAt(i) == '0') trailing++;
            else break;
        }

        int leading = 0;
        for (int i = 0; i < s2.length(); i++) {
            if (s2.charAt(i) == '0') leading++;
            else break;
        }

        if (trailing + leading >= c) {
