        long max = 0;
        long current = 0;

        for (char ch : s.toCharArray()) {
            if (ch == '0') {
                current++;
            } else {
                max = Math.max(max, current);
                current = 0;
            }
        }
        max = Math.max(max, current);
        return max;
    }

    static long findFirstPosition(String s, long c) {
        long current = 0;

        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '0') {
                current++;
                if (current == c) {
                    return i - c + 1;
                }
            } else {
                current = 0;
            }
        }
        return -1;
    }
}

