        string channelStr = to_string(channel);
        bool canMake = true;

        for (char digit : channelStr) {
            if (broken.count(digit)) {
                canMake = false;
                break;
            }
        }

        if (canMake) {
            int press = channelStr.length() + abs(channel - n);
            minPress = min(minPress, press);
        }
    }

    cout << minPress << endl;
    return 0;
}

