public class Main {
    static Map<String, List<String>> graph = new HashMap<>();
    static Map<String, Integer> scores = new HashMap<>();
    static Set<String> inProgress = new HashSet<>();

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        sc.nextLine();

        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().split(" ");
            String target = parts[0];
            int count = Integer.parseInt(parts[1]);

            graph.putIfAbsent(target, new ArrayList<>());

            for (int j = 0; j < count; j++) {
                String source = parts[2 + j];
                graph.get(target).add(source);
                graph.putIfAbsent(source, new ArrayList<>());
            }
        }

        String query = sc.next();
        System.out.println(calculateScore(query));
        sc.close();
    }

    static int calculateScore(String site) {
        if (scores.containsKey(site)) {
            return scores.get(site);
        }

        if (inProgress.contains(site)) {
            return 0;
        }

        inProgress.add(site);
        int score = 1;

        if (graph.containsKey(site)) {
            for (String source : graph.get(site)) {
                if (!hasPath(site, source, new HashSet<>())) {
                    score += calculateScore(source);
                }
            }
        }

        inProgress.remove(site);
        scores.put(site, score);
        return score;
    }

    static boolean hasPath(String start, String target, Set<String> visited) {
        if (start.equals(target)) {
            return true;
        }

        if (visited.contains(start)) {
            return false;
        }

        visited.add(start);

        if (graph.containsKey(start)) {
            for (String source : graph.get(start)) {
                if (hasPath(source, target, visited)) {
                    return true;
                }
            }
        }

        return false;
    }
}

