# Find all islands using DFS (8-directional)
island_map = [[-1] * m for _ in range(n)]
island_count = 0

def dfs_island(x, y, island_id):
    stack = [(x, y)]
    island_map[x][y] = island_id

    while stack:
        cx, cy = stack.pop()
        # 8 directions for islands
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < n and 0 <= ny < m:
                    if grid[nx][ny] == 'x' and island_map[nx][ny] == -1:
                        island_map[nx][ny] = island_id
                        stack.append((nx, ny))

# Label all islands
for i in range(n):
    for j in range(m):
        if grid[i][j] == 'x' and island_map[i][j] == -1:
            dfs_island(i, j, island_count)
            island_count += 1

if island_count == 0:
    print(-1)
    sys.exit()

# For each island, find which islands it contains
contains = [set() for _ in range(island_count)]

# BFS from each island cell to find reachable seas and islands
for island_id in range(island_count):
    # Find all cells of this island
    island_cells = []
    for i in range(n):
        for j in range(m):
            if island_map[i][j] == island_id:
                island_cells.append((i, j))

    # BFS from border to find which other islands are enclosed
    visited = [[False] * m for _ in range(n)]
    queue = deque()

    # Start from edges (outside the grid)
    for i in range(n):
        for j in range(m):
            if i == 0 or i == n-1 or j == 0 or j == m-1:
                if grid[i][j] == '.':
                    queue.append((i, j))
                    visited[i][j] = True

    # BFS through seas (4-directional)
    while queue:
        x, y = queue.popleft()
        for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny]:
                if grid[nx][ny] == '.':
                    visited[nx][ny] = True
                    queue.append((nx, ny))

    # Islands not reachable from outside are contained
    for other_id in range(island_count):
        if other_id == island_id:
            continue

        # Check if any cell of other_id is unreachable
        enclosed = True
        for i in range(n):
            for j in range(m):
                if island_map[i][j] == other_id:
                    # Check if sea around it is reachable from outside
                    can_escape = False
                    for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
                        ni, nj = i + dx, j + dy
                        if 0 <= ni < n and 0 <= nj < m:
                            if grid[ni][nj] == '.' and visited[ni][nj]:
                                can_escape = True
                                break
                        else:
                            can_escape = True
                            break

                    if can_escape:
                        enclosed = False
                        break

            if not enclosed:
                break

        if enclosed:
            contains[island_id].add(other_id)

# Calculate heights
heights = [-1] * island_count

def calc_height(island_id):
