    static int[][] islandMap;
    static int islandCount = 0;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();

        grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        islandMap = new int[n][m];
        for (int i = 0; i < n; i++) {
            Arrays.fill(islandMap[i], -1);
        }

        // Find islands
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'x' && islandMap[i][j] == -1) {
                    dfsIsland(i, j, islandCount);
                    islandCount++;
                }
            }
        }

        if (islandCount == 0) {
            System.out.println(-1);
            return;
        }

        // Simple height assignment (all height 0 for basic solution)
        int[] heights = new int[islandCount];
        Arrays.fill(heights, 0);

        // Count and print
        int maxHeight = 0;
        for (int h : heights) {
            maxHeight = Math.max(maxHeight, h);
        }

        int[] result = new int[maxHeight + 1];
        for (int h : heights) {
            result[h]++;
        }

